INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9301, 'ក្នុងត្រីកោណកែងមួយដែលមានប្រវែងជ្រុងមុំកែង \(a\) និង \(b\) ហើយអ៊ីប៉ូតេនុស \(c\) តើរូបមន្តទ្រឹស្តីបទពីតាក័រណាត្រឹមត្រូវ?', 'g8-dbb11406ad.svg', '["\\(c = a + b\\)", "\\(c^2 = a^2 + b^2\\)", "\\(a^2 = b^2 + c^2\\)", "\\(c^2 = a^2 - b^2\\)"]', 1, NULL, 1, 'mcq', 'ទ្រឹស្តីបទពីតាក័រចែងថា ក្នុងត្រីកោណកែង ការេនៃអ៊ីប៉ូតេនុសស្មើផលបូកការេនៃជ្រុងមុំកែងទាំងពីរ ៖ \(c^2 = a^2 + b^2\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9302, 'ត្រីកោណកែងមួយមានរង្វាស់ជ្រុងមុំកែង \(a = 3\ \text{cm}\) និង \(b = 4\ \text{cm}\)។ គណនាប្រវែងអ៊ីប៉ូតេនុស \(c\)។', NULL, '["\\(7\\ \\text{cm}\\)", "\\(25\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(5\\ \\text{cm}\\)"]', 3, NULL, 1, 'mcq', 'តាមពីតាក័រ ៖ \(c = \sqrt{3^2 + 4^2} = \sqrt{9 + 16} = \sqrt{25} = 5\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9303, 'ត្រីកោណកែងមួយមានជ្រុងមុំកែង \(6\ \text{cm}\) និង \(8\ \text{cm}\)។ រកប្រវែងអ៊ីប៉ូតេនុស។', NULL, '["\\(12\\ \\text{cm}\\)", "\\(100\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)"]', 2, NULL, 1, 'mcq', '\(c = \sqrt{6^2 + 8^2} = \sqrt{36 + 64} = \sqrt{100} = 10\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9304, 'ត្រីកោណកែងមួយមានជ្រុងមុំកែង \(5\ \text{dm}\) និង \(12\ \text{dm}\)។ គណនាអ៊ីប៉ូតេនុស។', NULL, '["\\(13\\ \\text{dm}\\)", "\\(169\\ \\text{dm}\\)", "\\(17\\ \\text{dm}\\)", "\\(15\\ \\text{dm}\\)"]', 0, NULL, 1, 'mcq', '\(c = \sqrt{5^2 + 12^2} = \sqrt{25 + 144} = \sqrt{169} = 13\ \text{dm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9305, 'ត្រីកោណកែងមួយមានអ៊ីប៉ូតេនុស \(c = 10\ \text{cm}\) និងជ្រុងមុំកែងមួយ \(a = 6\ \text{cm}\)។ គណនាជ្រុងមុំកែងមួយទៀត \(b\)។', NULL, '["\\(12\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)"]', 1, NULL, 1, 'mcq', '\(b = \sqrt{c^2 - a^2} = \sqrt{10^2 - 6^2} = \sqrt{100 - 36} = \sqrt{64} = 8\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9306, 'ត្រីកោណកែង \(ABC\) កែងត្រង់ \(A\) មាន \(BC = 15\ \text{cm}\) និង \(AB = 9\ \text{cm}\)។ គណនា \(AC\)។', NULL, '["\\(6\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)"]', 3, NULL, 1, 'mcq', '\(AC = \sqrt{BC^2 - AB^2} = \sqrt{225 - 81} = \sqrt{144} = 12\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9307, 'ការេមួយមានរង្វាស់ជ្រុង \(a\)។ តើប្រវែងអង្កត់ទ្រូង \(d\) នៃការេស្មើនឹងប៉ុន្មាន?', NULL, '["\\(d = a\\sqrt{2}\\)", "\\(d = a\\sqrt{3}\\)", "\\(d = \\dfrac{a}{\\sqrt{2}}\\)", "\\(d = 2a\\)"]', 0, NULL, 1, 'mcq', '\(d^2 = a^2 + a^2 = 2a^2 \Rightarrow d = \sqrt{2a^2} = a\sqrt{2}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9308, 'ចតុកោណកែងមួយមានបណ្តោយ \(8\ \text{cm}\) និងទទឹង \(6\ \text{cm}\)។ គណនាប្រវែងអង្កត់ទ្រូង។', NULL, '["\\(14\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(48\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 3, NULL, 1, 'mcq', '\(d = \sqrt{8^2 + 6^2} = \sqrt{64 + 36} = \sqrt{100} = 10\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9309, 'ក្នុងចំណោមប្រវែងជ្រុងទាំង 3 ខាងក្រោម តើមួយណាជាជ្រុងនៃត្រីកោណកែង?', NULL, '["\\(3,\\ 4,\\ 5\\)", "\\(5,\\ 6,\\ 7\\)", "\\(4,\\ 5,\\ 6\\)", "\\(2,\\ 3,\\ 4\\)"]', 0, NULL, 1, 'mcq', '\(3^2 + 4^2 = 9 + 16 = 25 = 5^2\) ដូចនេះ \((3, 4, 5)\) ជាជ្រុងនៃត្រីកោណកែង', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
