INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9310, 'ក្នុងការស្រាយបញ្ជាក់ទ្រឹស្តីបទពីតាក័រដោយផ្គុំត្រីកោណកែង 4 ដែលមានជ្រុងមុំកែង \(a\) និង \(b\) ជុំវិញការេកណ្តាល \(c^2\) តើការេធំខាងក្រៅមានរង្វាស់ជ្រុងស្មើនឹងប៉ុន្មាន?', 'g8-393eeb5e5c.svg', '["\\(c\\)", "\\(a + b\\)", "\\(ab\\)", "\\(\\sqrt{a^2 + b^2}\\)"]', 1, NULL, 1, 'mcq', 'ការេធំខាងក្រៅផ្គុំដោយជ្រុង \(a\) និង \(b\) ដូច្នេះជ្រុងរបស់វាគឺ \(a + b\)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9311, 'ត្រីកោណកែងមួយមានជ្រុងមុំកែង \(8\ \text{cm}\) និង \(15\ \text{cm}\)។ គណនាអ៊ីប៉ូតេនុស។', NULL, '["\\(16\\ \\text{cm}\\)", "\\(17\\ \\text{cm}\\)", "\\(19\\ \\text{cm}\\)", "\\(23\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', '\(c = \sqrt{8^2 + 15^2} = \sqrt{64 + 225} = \sqrt{289} = 17\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9312, 'ត្រីកោណកែងមួយមានអ៊ីប៉ូតេនុស \(25\ \text{m}\) និងជ្រុងមុំកែងមួយ \(7\ \text{m}\)។ គណនាជ្រុងមុំកែងមួយទៀត។', NULL, '["\\(18\\ \\text{m}\\)", "\\(24\\ \\text{m}\\)", "\\(20\\ \\text{m}\\)", "\\(22\\ \\text{m}\\)"]', 1, NULL, 2, 'mcq', '\(b = \sqrt{25^2 - 7^2} = \sqrt{625 - 49} = \sqrt{576} = 24\ \text{m}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9313, 'ត្រីកោណកែង \(ABC\) កែងត្រង់ \(B\) មាន \(AC = 26\ \text{cm}\) និង \(BC = 10\ \text{cm}\)។ គណនា \(AB\)។', NULL, '["\\(24\\ \\text{cm}\\)", "\\(22\\ \\text{cm}\\)", "\\(20\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)"]', 0, NULL, 2, 'mcq', '\(AB = \sqrt{26^2 - 10^2} = \sqrt{676 - 100} = \sqrt{576} = 24\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9314, 'ត្រីកោណកែងសមបាតមួយមានជ្រុងមុំកែងស្មើគ្នា \(a = b = 5\ \text{cm}\)។ គណនាប្រវែងអ៊ីប៉ូតេនុស។', NULL, '["\\(5\\sqrt{3}\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(25\\ \\text{cm}\\)", "\\(5\\sqrt{2}\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(c = \sqrt{5^2 + 5^2} = \sqrt{50} = 5\sqrt{2}\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9315, 'ត្រីកោណកែងសមបាតមួយមានអ៊ីប៉ូតេនុសប្រវែង \(8\sqrt{2}\ \text{cm}\)។ គណនារង្វាស់ជ្រុងមុំកែងនីមួយៗ។', NULL, '["\\(4\\sqrt{2}\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(c = a\sqrt{2} = 8\sqrt{2} \Rightarrow a = 8\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9316, 'ការេមួយមានប្រវែងអង្កត់ទ្រូង \(12\ \text{cm}\)។ គណនាប្រវែងជ្រុងនៃការេនោះ។', NULL, '["\\(12\\sqrt{2}\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(3\\sqrt{2}\\ \\text{cm}\\)", "\\(6\\sqrt{2}\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(a = \dfrac{d}{\sqrt{2}} = \dfrac{12}{\sqrt{2}} = \dfrac{12\sqrt{2}}{2} = 6\sqrt{2}\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9317, 'ចតុកោណស្មើមួយមានអង្កត់ទ្រូងទាំងពីរប្រវែង \(16\ \text{cm}\) និង \(12\ \text{cm}\)។ គណនាប្រវែងជ្រុងនៃចតុកោណស្មើ។', NULL, '["\\(20\\ \\text{cm}\\)", "\\(14\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', 'អង្កត់ទ្រូងចតុកោណស្មើកាត់គ្នាកែងត្រង់ចំណុចកណ្តាល ៖ \(a = \sqrt{8^2 + 6^2} = \sqrt{64 + 36} = 10\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
