INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9318, 'ជណ្តើរមួយប្រវែង \(10\ \text{m}\) ផ្អែកលើជញ្ជាំងអគារដោយគល់ជណ្តើរនៅចម្ងាយ \(6\ \text{m}\) ពីជញ្ជាំង។ តើចុងជណ្តើរប៉ះជញ្ជាំងកម្ពស់ប៉ុន្មានពីដី?', 'g8-ba152fd42f.svg', '["\\(8\\ \\text{m}\\)", "\\(7\\ \\text{m}\\)", "\\(9\\ \\text{m}\\)", "\\(4\\ \\text{m}\\)"]', 0, NULL, 2, 'mcq', '\(h = \sqrt{10^2 - 6^2} = \sqrt{100 - 36} = \sqrt{64} = 8\ \text{m}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9319, 'តើត្រីកោណដែលមានរង្វាស់ជ្រុង \(5\ \text{cm},\ 12\ \text{cm},\ 13\ \text{cm}\) ជាប្រភេទត្រីកោណអ្វី?', NULL, '["ត្រីកោណសមបាតមិនកែង", "ត្រីកោណទាល", "ត្រីកោណស្រួច", "ត្រីកោណកែង"]', 3, NULL, 2, 'mcq', '\(5^2 + 12^2 = 25 + 144 = 169 = 13^2\) តាមទ្រឹស្តីបទច្រាសពីតាក័រ វាជាត្រីកោណកែង', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9320, 'ត្រីកោណមួយមានរង្វាស់ជ្រុង \(4\ \text{cm},\ 6\ \text{cm},\ 8\ \text{cm}\)។ តើត្រីកោណនេះជាប្រភេទអ្វី?', NULL, '["ត្រីកោណទាល", "ត្រីកោណស្រួច", "ត្រីកោណសម័ង្ស", "ត្រីកោណកែង"]', 0, NULL, 2, 'mcq', '\(4^2 + 6^2 = 16 + 36 = 52 < 8^2 = 64\) ដោយ \(c^2 > a^2 + b^2\) នោះវាជាត្រីកោណទាល', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9321, 'ត្រីកោណមួយមានរង្វាស់ជ្រុង \(5\ \text{cm},\ 6\ \text{cm},\ 7\ \text{cm}\)។ តើត្រីកោណនេះជាប្រភេទអ្វី?', NULL, '["ត្រីកោណទាល", "ត្រីកោណកែង", "ត្រីកោណកែងសមបាត", "ត្រីកោណស្រួច"]', 3, NULL, 2, 'mcq', '\(5^2 + 6^2 = 25 + 36 = 61 > 7^2 = 49\) ដោយ \(c^2 < a^2 + b^2\) នោះវាជាត្រីកោណស្រួច', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9322, 'ក្នុងគំនូសគូសបន្តបន្ទាប់ (កង្ហារពីតាក័រ) ៖ ត្រីកោណកែងទី១ មានជ្រុង \(1\) និង \(1\) នាំឱ្យអ៊ីប៉ូតេនុស \(\sqrt{2}\)។ ត្រីកោណកែងទី២ មានជ្រុង \(\sqrt{2}\) និង \(1\)។ គណនាអ៊ីប៉ូតេនុសនៃត្រីកោណទី២។', NULL, '["\\(\\sqrt{5}\\)", "\\(\\sqrt{2}\\)", "\\(2\\)", "\\(\\sqrt{3}\\)"]', 3, NULL, 2, 'mcq', '\(x = \sqrt{(\sqrt{2})^2 + 1^2} = \sqrt{2 + 1} = \sqrt{3}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9323, 'ក្នុងប្លង់កូអរដោនេ រកចម្ងាយរវាងចំណុច \(A(1, 2)\) និង \(B(4, 6)\)។', NULL, '["\\(\\sqrt{7}\\)", "\\(25\\)", "\\(7\\)", "\\(5\\)"]', 3, NULL, 2, 'mcq', '\(AB = \sqrt{(4-1)^2 + (6-2)^2} = \sqrt{3^2 + 4^2} = \sqrt{9 + 16} = 5\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9324, 'គូបមួយមានរង្វាស់គែម \(a\)។ តើប្រវែងអង្កត់ទ្រូងនៃគូបស្មើនឹងប៉ុន្មាន?', NULL, '["\\(3a\\)", "\\(\\sqrt{3a}\\)", "\\(a\\sqrt{3}\\)", "\\(a\\sqrt{2}\\)"]', 2, NULL, 2, 'mcq', 'អង្កត់ទ្រូងបាតគឺ \(d_1 = a\sqrt{2}\) នាំឱ្យអង្កត់ទ្រូងគូប \(d = \sqrt{d_1^2 + a^2} = \sqrt{2a^2 + a^2} = a\sqrt{3}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g8-88957e3ab8.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9325, 'ប្រលេឡេពីប៉ែតកែងមួយមានវិមាត្របណ្តោយ \(12\ \text{cm}\), ទទឹង \(4\ \text{cm}\) និងកម្ពស់ \(3\ \text{cm}\)។ គណនាប្រវែងអង្កត់ទ្រូងនៃប្រលេឡេពីប៉ែតនោះ។', 'g8-88957e3ab8.svg', '["\\(15\\ \\text{cm}\\)", "\\(13\\ \\text{cm}\\)", "\\(19\\ \\text{cm}\\)", "\\(\\sqrt{160}\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', '\(d = \sqrt{12^2 + 4^2 + 3^2} = \sqrt{144 + 16 + 9} = \sqrt{169} = 13\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9326, 'គូបមួយមានប្រវែងអង្កត់ទ្រូង \(d = 6\sqrt{3}\ \text{cm}\)។ គណនាផ្ទៃក្រឡាសរុបនៃគូបនោះ។', NULL, '["\\(108\\ \\text{cm}^2\\)", "\\(144\\ \\text{cm}^2\\)", "\\(36\\ \\text{cm}^2\\)", "\\(216\\ \\text{cm}^2\\)"]', 3, NULL, 3, 'mcq', '\(d = a\sqrt{3} = 6\sqrt{3} \Rightarrow a = 6\ \text{cm}\) ផ្ទៃសរុប ៖ \(S = 6a^2 = 6 \times 36 = 216\ \text{cm}^2\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9327, 'ត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មាន \(AB = 12\ \text{cm}\) និង \(AC = 16\ \text{cm}\)។ គណនាកម្ពស់ \(AH\) គូសលើអ៊ីប៉ូតេនុស \(BC\)។', NULL, '["\\(11.2\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)", "\\(8.4\\ \\text{cm}\\)", "\\(9.6\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', '\(BC = \sqrt{12^2 + 16^2} = 20\ \text{cm}\)។ តាមផ្ទៃក្រឡា ៖ \(AH = \dfrac{AB \times AC}{BC} = \dfrac{12 \times 16}{20} = 9.6\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9328, 'ត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មាន \(AB = 12\ \text{cm}\), \(AC = 16\ \text{cm}\) និងកម្ពស់ \(AH\) (\(H \in BC\))។ គណនាប្រវែងចំណោល \(BH\)។', NULL, '["\\(6.4\\ \\text{cm}\\)", "\\(7.2\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)", "\\(12.8\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', '\(BC = 20\ \text{cm}\)។ តាមទំនាក់ទំនងក្នុងត្រីកោណកែង ៖ \(AB^2 = BH \times BC \Rightarrow BH = \dfrac{144}{20} = 7.2\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9329, 'ត្រីកោណសម័ង្សមួយមានរង្វាស់ជ្រុង \(8\ \text{cm}\)។ គណនាកម្ពស់នៃត្រីកោណសម័ង្សនោះ។', NULL, '["\\(4\\sqrt{3}\\ \\text{cm}\\)", "\\(8\\sqrt{3}\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', 'កម្ពស់បំបែកជាត្រីកោណកែងមានជ្រុងមុំកែង \(4\ \text{cm}\) និងអ៊ីប៉ូតេនុស \(8\ \text{cm}\) ៖ \(h = \sqrt{8^2 - 4^2} = \sqrt{64 - 16} = \sqrt{48} = 4\sqrt{3}\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9330, 'ត្រីកោណសមបាត \(ABC\) មាន \(AB = AC = 13\ \text{cm}\) និងបាត \(BC = 10\ \text{cm}\)។ គណនាផ្ទៃក្រឡានៃត្រីកោណ \(ABC\)។', NULL, '["\\(130\\ \\text{cm}^2\\)", "\\(120\\ \\text{cm}^2\\)", "\\(60\\ \\text{cm}^2\\)", "\\(65\\ \\text{cm}^2\\)"]', 2, NULL, 3, 'mcq', 'កម្ពស់ \(AH\) ធ្លាក់ចំកណ្តាលបាត ៖ \(BH = 5\ \text{cm}\) នាំឱ្យ \(AH = \sqrt{13^2 - 5^2} = 12\ \text{cm}\)។ ផ្ទៃ ៖ \(S = \dfrac{10 \times 12}{2} = 60\ \text{cm}^2\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9331, 'ចតុកោណព្នាយសមបាត \(ABCD\) មានបាតតូច \(AB = 6\ \text{cm}\), បាតធំ \(CD = 16\ \text{cm}\) និងជ្រុងទ្រេត \(AD = BC = 13\ \text{cm}\)។ គណនាកម្ពស់ \(h\) នៃចតុកោណព្នាយ។', NULL, '["\\(11\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(15\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', 'ចំណោលកែងលើបាតធំ ៖ \(x = \dfrac{16 - 6}{2} = 5\ \text{cm}\) នាំឱ្យកម្ពស់ \(h = \sqrt{13^2 - 5^2} = \sqrt{169 - 25} = 12\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9332, 'ទូខោអាវមួយមានកម្ពស់ \(2.4\ \text{m}\) និងជម្រៅ \(0.7\ \text{m}\)។ គេត្រូវផ្តេកទូលើកម្រាលដើម្បីដំឡើង រួចលើកបញ្ឈរឡើងវិញ។ បើពិដានបន្ទប់មានកម្ពស់ \(2.45\ \text{m}\) តើទូនោះអាចលើកបញ្ឈរឡើងវិញបានឬទេ?', NULL, '["មិនបានទេ ព្រោះអង្កត់ទ្រូងទូគឺ \\(2.5\\ \\text{m} > 2.45\\ \\text{m}\\)", "បាន ព្រោះកម្ពស់ទូ \\(2.4\\ \\text{m} < 2.45\\ \\text{m}\\)", "មិនបានទេ ព្រោះផលបូកវិមាត្រ \\(3.1\\ \\text{m} > 2.45\\ \\text{m}\\)", "បាន ព្រោះជម្រៅទូត្រឹមតែ \\(0.7\\ \\text{m}\\)"]', 0, NULL, 3, 'mcq', 'ពេលលើកបញ្ឈរ ចម្ងាយខ្ពស់បំផុតគឺអង្កត់ទ្រូងទូ ៖ \(d = \sqrt{2.4^2 + 0.7^2} = \sqrt{5.76 + 0.49} = \sqrt{6.25} = 2.5\ \text{m} > 2.45\ \text{m}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9333, 'សួនច្បាររាងចតុកោណកែងមានបណ្តោយ \(80\ \text{m}\) និងទទឹង \(60\ \text{m}\)។ សិស្សម្នាក់ដើរកាត់តាមផ្លូវអង្កត់ទ្រូងជំនួសឱ្យការដើរតាមគែមទាំងពីរ។ តើគាត់កាត់បន្ថយចម្ងាយដើរបានប៉ុន្មានម៉ែត្រ?', NULL, '["\\(100\\ \\text{m}\\)", "\\(40\\ \\text{m}\\)", "\\(20\\ \\text{m}\\)", "\\(50\\ \\text{m}\\)"]', 1, NULL, 3, 'mcq', 'ដើរតាមគែម ៖ \(80 + 60 = 140\ \text{m}\)។ ដើរតាមអង្កត់ទ្រូង ៖ \(d = \sqrt{80^2 + 60^2} = 100\ \text{m}\)។ ចម្ងាយបន្ថយបាន ៖ \(140 - 100 = 40\ \text{m}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9334, 'បង្គោលអង់តែនទូរគមនាគមន៍មួយមានកម្ពស់ \(24\ \text{m}\)។ គេចងខ្សែលួសទប់ពីកំពូលបង្គោលទៅដីនៅចម្ងាយ \(7\ \text{m}\) ពីគល់បង្គោល។ រកប្រវែងខ្សែលួសនោះ។', NULL, '["\\(31\\ \\text{m}\\)", "\\(26\\ \\text{m}\\)", "\\(25\\ \\text{m}\\)", "\\(28\\ \\text{m}\\)"]', 2, NULL, 3, 'mcq', '\(L = \sqrt{24^2 + 7^2} = \sqrt{576 + 49} = \sqrt{625} = 25\ \text{m}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9335, 'កញ្ចក់ទូរទស្សន៍មួយមានទទឹង \(80\ \text{cm}\) និងបណ្តោយ \(60\ \text{cm}\)។ គណនាប្រវែងអង្កត់ទ្រូងនៃកញ្ចក់ទូរទស្សន៍នោះគិតជាសង់ទីម៉ែត្រ។', NULL, '["\\(100\\ \\text{cm}\\)", "\\(120\\ \\text{cm}\\)", "\\(90\\ \\text{cm}\\)", "\\(140\\ \\text{cm}\\)"]', 0, NULL, 3, 'mcq', '\(d = \sqrt{80^2 + 60^2} = \sqrt{6\,400 + 3\,600} = \sqrt{10\,000} = 100\ \text{cm}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9336, 'យន្តហោះពីរហោះចេញពីចំណុច \(O\) ដំណាលគ្នាតាមទិសពីរដែលកែងគ្នា។ យន្តហោះទី១ ហោះបានចម្ងាយ \(300\ \text{km}\) និងយន្តហោះទី២ ហោះបាន \(400\ \text{km}\)។ តើយន្តហោះទាំងពីរនៅឃ្លាតពីគ្នាចម្ងាយប៉ុន្មាន?', NULL, '["\\(700\\ \\text{km}\\)", "\\(500\\ \\text{km}\\)", "\\(450\\ \\text{km}\\)", "\\(600\\ \\text{km}\\)"]', 1, NULL, 3, 'mcq', '\(d = \sqrt{300^2 + 400^2} = \sqrt{90\,000 + 160\,000} = \sqrt{250\,000} = 500\ \text{km}\)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 1, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9337, 'ត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មានជ្រុងមុំកែង \(AB = 9\ \text{cm}\) និង \(AC = 12\ \text{cm}\)។
ក. សរសេររូបមន្តទ្រឹស្តីបទពីតាក័រសម្រាប់ត្រីកោណនេះ។
ខ. គណនាប្រវែងអ៊ីប៉ូតេនុស \(BC\)។', 'g8-dbb11406ad.svg', '[]', 0, NULL, 5, 'writing', 'ក. រូបមន្តទ្រឹស្តីបទពីតាក័រ ៖ \(BC^2 = AB^2 + AC^2\) (2 ពិន្ទុ)
ខ. ជំនួសតម្លៃ ៖ \(BC^2 = 9^2 + 12^2 = 81 + 144 = 225\) (2 ពិន្ទុ)
ទាញបាន \(BC = \sqrt{225} = 15\ \text{cm}\) (1 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'easy', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9338, 'គេឱ្យត្រីកោណ \(MNP\) ដែលមានរង្វាស់ជ្រុង \(MN = 7\ \text{cm}\), \(NP = 24\ \text{cm}\) និង \(MP = 25\ \text{cm}\)។
ក. គណនា \(MN^2 + NP^2\) និង \(MP^2\)។
ខ. ប្រៀបធៀបតម្លៃទាំងពីរ រួចសន្និដ្ឋានពីប្រភេទត្រីកោណ \(MNP\) និងបញ្ជាក់ថាតើវាកែងត្រង់កំពូលណា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. គណនា ៖ \(MN^2 + NP^2 = 7^2 + 24^2 = 49 + 576 = 625\) (2 ពិន្ទុ)
គណនា ៖ \(MP^2 = 25^2 = 625\) (1 ពិន្ទុ)
ខ. ដោយ \(MP^2 = MN^2 + NP^2 = 625\) តាមទ្រឹស្តីបទច្រាសពីតាក័រ ត្រីកោណ \(MNP\) ជាត្រីកោណកែងត្រង់កំពូល \(N\) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9339, 'ការេ \(ABCD\) មួយមានរង្វាស់ជ្រុង \(AB = 8\ \text{cm}\)។
ក. គណនាប្រវែងអង្កត់ទ្រូង \(AC\) ជាទម្រង់រ៉ាឌីកាល់ \(a\sqrt{2}\)។
ខ. គណនាផ្ទៃក្រឡានៃការេតាមពីររបៀប ៖ តាមជ្រុង និងតាមអង្កត់ទ្រូង (\(S = \dfrac{d^2}{2}\)) រួចផ្ទៀងផ្ទាត់ថាលទ្ធផលដូចគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ត្រីកោណ \(ABC\) កែងត្រង់ \(B\) ៖ \(AC = \sqrt{8^2 + 8^2} = \sqrt{64 \times 2} = 8\sqrt{2}\ \text{cm}\) (2 ពិន្ទុ)
ខ. របៀបទី១ តាមជ្រុង ៖ \(S = 8^2 = 64\ \text{cm}^2\) (1 ពិន្ទុ)
របៀបទី២ តាមអង្កត់ទ្រូង ៖ \(S = \dfrac{(8\sqrt{2})^2}{2} = \dfrac{64 \times 2}{2} = 64\ \text{cm}^2\) (លទ្ធផលដូចគ្នា) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9340, 'ជណ្តើរមួយមានប្រវែង \(8\ \text{m}\) ផ្អែកលើជញ្ជាំងអគារដោយគល់ជណ្តើរនៅចម្ងាយ \(2\ \text{m}\) ពីជញ្ជាំង។
ក. សង់រូបគំរូនៃត្រីកោណកែងតំណាងឱ្យស្ថានភាពនេះ។
ខ. គណនាកម្ពស់ \(h\) ដែលចុងជណ្តើរប៉ះជញ្ជាំងជាទម្រង់រ៉ាឌីកាល់សម្រួល និងជាតម្លៃប្រហែល (យក \(\sqrt{15} pprox 3.87\))។', 'g8-ba152fd42f.svg', '[]', 0, NULL, 5, 'writing', 'ក. ជញ្ជាំងកែងនឹងដី បង្កើតបានត្រីកោណកែងមានអ៊ីប៉ូតេនុស \(L = 8\ \text{m}\) និងបាត \(d = 2\ \text{m}\) (1 ពិន្ទុ)
ខ. តាមទ្រឹស្តីបទពីតាក័រ ៖ \(h^2 = 8^2 - 2^2 = 64 - 4 = 60\) (2 ពិន្ទុ)
ទាញបាន \(h = \sqrt{60} = 2\sqrt{15}\ \text{m} pprox 2 \times 3.87 = 7.74\ \text{m}\) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9341, 'ចតុកោណស្មើ \(ABCD\) មានអង្កត់ទ្រូងកាត់គ្នាកែងត្រង់ \(O\) ដោយ \(AC = 24\ \text{cm}\) និង \(BD = 10\ \text{cm}\)។
ក. គណនាប្រវែង \(OA\) និង \(OB\)។
ខ. គណនាប្រវែងជ្រុង \(AB\) និងបរិមាត្រនៃចតុកោណស្មើ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ទ្រូងកាត់គ្នាកែងត្រង់ចំណុចកណ្តាល ៖ \(OA = \dfrac{24}{2} = 12\ \text{cm}\) និង \(OB = \dfrac{10}{2} = 5\ \text{cm}\) (2 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែង \(OAB\) ៖ \(AB = \sqrt{12^2 + 5^2} = \sqrt{144 + 25} = \sqrt{169} = 13\ \text{cm}\) (2 ពិន្ទុ)
បរិមាត្រនៃចតុកោណស្មើ ៖ \(P = 4 \times 13 = 52\ \text{cm}\) (1 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'medium', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9342, 'ពិនិត្យការេធំដែលមានជ្រុង \((a+b)\) ក្នុងរូបខាងស្តាំ ដែលផ្គុំឡើងដោយត្រីកោណកែងចំនួន 4 (ជ្រុងមុំកែង \(a, b\)) និងការេខាងក្នុងដែលមានជ្រុង \(c\)។
ក. សរសេរកន្សោមផ្ទៃក្រឡាការេធំជាអនុគមន៍នៃ \(a\) និង \(b\)។
ខ. សរសេរផលបូកផ្ទៃក្រឡានៃត្រីកោណកែងទាំង 4 និងការេកណ្តាល។
គ. ទាញស្រាយបញ្ជាក់ទ្រឹស្តីបទពីតាក័រ \(c^2 = a^2 + b^2\)។', 'g8-393eeb5e5c.svg', '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាការេធំ ៖ \(S_{\text{ធំ}} = (a+b)^2 = a^2 + 2ab + b^2\) (2 ពិន្ទុ)
ខ. ផ្ទៃត្រីកោណកែងទាំងបួន ៖ \(4 \times \dfrac{1}{2}ab = 2ab\); ផ្ទៃការេកណ្តាល ៖ \(c^2\) (1 ពិន្ទុ)
គ. ដោយ \(S_{\text{ធំ}} = c^2 + 2ab \Rightarrow a^2 + 2ab + b^2 = c^2 + 2ab \Rightarrow c^2 = a^2 + b^2\) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9343, 'ត្រីកោណ \(ABC\) កែងត្រង់ \(A\) មាន \(BC = 20\ \text{cm}\) និង \(AC = 16\ \text{cm}\)។ \(AH\) ជាកម្ពស់គូសលើ \(BC\)។
ក. គណនារង្វាស់ជ្រុង \(AB\)។
ខ. គណនាកម្ពស់ \(AH\)។
គ. គណនាប្រវែងកំណាត់ \(BH\) និង \(HC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(AB = \sqrt{BC^2 - AC^2} = \sqrt{20^2 - 16^2} = \sqrt{400 - 256} = \sqrt{144} = 12\ \text{cm}\) (1 ពិន្ទុ)
ខ. តាមផ្ទៃក្រឡា \(S = \dfrac{AB \times AC}{2} = \dfrac{BC \times AH}{2} \Rightarrow AH = \dfrac{12 \times 16}{20} = 9.6\ \text{cm}\) (2 ពិន្ទុ)
គ. \(BH = \sqrt{12^2 - 9.6^2} = 7.2\ \text{cm}\) និង \(HC = 20 - 7.2 = 12.8\ \text{cm}\) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9344, 'គេឱ្យគូបមួយដែលមានរង្វាស់គែម \(a = 4\ \text{cm}\)។
ក. គណនាប្រវែងអង្កត់ទ្រូងបាត \(d_1\)។
ខ. បង្ហាញថាអង្កត់ទ្រូងគូប \(d\) ផ្ទៀងផ្ទាត់ \(d = a\sqrt{3}\) រួចគណនាតម្លៃពិតប្រាកដរបស់វា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ទ្រូងបាត ៖ \(d_1 = \sqrt{a^2 + a^2} = \sqrt{4^2 + 4^2} = 4\sqrt{2}\ \text{cm}\) (2 ពិន្ទុ)
ខ. ត្រីកោណកែងបង្កើតដោយ \(d_1\), កម្ពស់ \(a\) និងអង្កត់ទ្រូង \(d\) ៖ \(d = \sqrt{d_1^2 + a^2} = \sqrt{(a\sqrt{2})^2 + a^2} = \sqrt{3a^2} = a\sqrt{3}\) (2 ពិន្ទុ)
ជំនួស \(a = 4\ \text{cm} \Rightarrow d = 4\sqrt{3}\ \text{cm}\) (1 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9345, 'ក្នុងតម្រុយអ័ក្សអរតូណរម៉េ គេឱ្យចំណុច \(A(-2, 9)\) និង \(B(10, 4)\)។
ក. រកប្រវែងចំណោលដេក \(|x_B - x_A|\) និងចំណោលឈរ \(|y_B - y_A|\)។
ខ. គណនាចម្ងាយ \(AB\)។
គ. បើចំណុច \(C(10, 9)\) បង្កើតបានត្រីកោណ \(ABC\) បញ្ជាក់ថាតើត្រីកោណ \(ABC\) ជាប្រភេទត្រីកោណអ្វី?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចំណោលដេក ៖ \(|10 - (-2)| = 12\); ចំណោលឈរ ៖ \(|4 - 9| = 5\) (2 ពិន្ទុ)
ខ. តាមរូបមន្តចម្ងាយ (ពីតាក័រ) ៖ \(AB = \sqrt{12^2 + 5^2} = \sqrt{144 + 25} = \sqrt{169} = 13\) (2 ពិន្ទុ)
គ. ចំណុច \(C(10, 9)\) មាន \(AC = 12, BC = 5\) នាំឱ្យ \(AC^2 + BC^2 = 12^2 + 5^2 = 169 = AB^2\) ដូចនេះ \(\Delta ABC\) កែងត្រង់ \(C\) (1 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'hard', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9346, 'យន្តហោះពីរហោះចេញពីព្រលានយន្តហោះ \(O\) ដំណាលគ្នានៅម៉ោង \(8:00\) ព្រឹក ដោយយន្តហោះ \(A\) ហោះទៅទិសខាងជើងដោយល្បឿន \(600\ \text{km/h}\) និងយន្តហោះ \(B\) ហោះទៅទិសខាងកើតដោយល្បឿន \(800\ \text{km/h}\)។
ក. គណនាចម្ងាយចរនៃយន្តហោះនីមួយៗនៅម៉ោង \(9:30\) ព្រឹក (រយៈពេល \(1.5\ \text{ម៉ោង}\))។
ខ. គណនាចម្ងាយរវាងយន្តហោះទាំងពីរនៅម៉ោង \(9:30\) ព្រឹក។
គ. ពន្យល់ហេតុអ្វីបានជាយើងអាចប្រើទ្រឹស្តីបទពីតាក័រក្នុងករណីនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចម្ងាយយន្តហោះ \(A\) ៖ \(d_A = 600 \times 1.5 = 900\ \text{km}\); ចម្ងាយយន្តហោះ \(B\) ៖ \(d_B = 800 \times 1.5 = 1\,200\ \text{km}\) (2 ពិន្ទុ)
ខ. ចម្ងាយរវាងយន្តហោះទាំងពីរ ៖ \(AB = \sqrt{900^2 + 1\,200^2} = \sqrt{810\,000 + 1\,440\,000} = \sqrt{2\,250\,000} = 1\,500\ \text{km}\) (2 ពិន្ទុ)
គ. ទិសខាងជើងនិងទិសខាងកើតកែងគ្នាបង្កើតបានមុំ \(90^\circ\) នាំឱ្យគន្លងហោះហើរ និងចម្ងាយរវាងយន្តហោះទាំងពីរបង្កើតបានជាត្រីកោណកែង (1 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9347, 'គេសង់ត្រីកោណសម័ង្សបីគឺ \(\Delta BCR, \Delta ACQ\) និង \(\Delta ABP\) លើជ្រុង \(a, b, c\) នៃត្រីកោណកែង \(ABC\) (កែងត្រង់ \(C\)) រៀងគ្នា។
ក. សរសេររូបមន្តផ្ទៃក្រឡានៃត្រីកោណសម័ង្សដែលមានជ្រុង \(s\)។
ខ. គណនាផ្ទៃក្រឡា \(S_{BCR}, S_{ACQ}\) និង \(S_{ABP}\)។
គ. បង្ហាញថា \(S_{ABP} = S_{BCR} + S_{ACQ}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. រូបមន្តផ្ទៃត្រីកោណសម័ង្សជ្រុង \(s\) គឺ ៖ \(S = \dfrac{\sqrt{3}}{4}s^2\) (1 ពិន្ទុ)
ខ. ផ្ទៃទាំងបី ៖ \(S_{BCR} = \dfrac{\sqrt{3}}{4}a^2\), \(S_{ACQ} = \dfrac{\sqrt{3}}{4}b^2\), \(S_{ABP} = \dfrac{\sqrt{3}}{4}c^2\) (2 ពិន្ទុ)
គ. ផលបូក ៖ \(S_{BCR} + S_{ACQ} = \dfrac{\sqrt{3}}{4}(a^2 + b^2)\)។ ដោយ \(a^2 + b^2 = c^2\) (ពីតាក័រ) នោះ \(S_{BCR} + S_{ACQ} = \dfrac{\sqrt{3}}{4}c^2 = S_{ABP}\) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9348, 'វិស្វករម្នាក់ត្រូវដំឡើងខ្សែលួសទប់បង្គោលអង់តែនកម្ពស់ \(36\ \text{m}\)។ តាមបទដ្ឋានសុវត្ថិភាព មុំរវាងខ្សែលួសនិងដីត្រូវស្ថិតនៅចន្លោះពី \(45^\circ\) ទៅ \(60^\circ\)។ គាត់សម្រេចចងគល់ខ្សែលួសនៅចម្ងាយ \(27\ \text{m}\) ពីគល់បង្គោល។
ក. គណនាប្រវែងខ្សែលួសដែលត្រូវការសម្រាប់ខ្សែមួយខ្សែ។
ខ. បើបង្គោលនោះត្រូវការខ្សែលួសទប់ចំនួន 4 ទិសស្មើគ្នា តើត្រូវប្រើខ្សែលួសសរុបប្រវែងប៉ុន្មាន?
គ. បើខ្សែលួស ១ ម៉ែត្រមានតម្លៃ \(3.5\$\) គណនាថ្លៃទិញខ្សែលួសទាំងអស់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រវែងខ្សែមួយ ៖ \(L = \sqrt{36^2 + 27^2} = \sqrt{1\,296 + 729} = \sqrt{2\,025} = 45\ \text{m}\) (2 ពិន្ទុ)
ខ. ប្រវែងខ្សែសរុបសម្រាប់ 4 ទិស ៖ \(45 \times 4 = 180\ \text{m}\) (2 ពិន្ទុ)
គ. ថ្លៃខ្សែលួសសរុប ៖ \(180 \times 3.5 = 630\$\) (1 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9349, 'ទ្វារបន្ទប់មួយមានរាងចតុកោណកែងទទឹង \(1\ \text{m}\) និងកម្ពស់ \(2\ \text{m}\)។ ជាងម្នាក់ចង់សែងបន្ទះក្តារបន្ទះមូលមួយផ្ទាំងដែលមានអង្កត់ផ្ចិត \(2.2\ \text{m}\) ចូលក្នុងបន្ទប់។
ក. គណនាប្រវែងអង្កត់ទ្រូងនៃទ្វារបន្ទប់ (យក \(\sqrt{5} pprox 2.236\ \text{m}\))។
ខ. តើជាងនោះអាចសែងបន្ទះក្តារមូលនោះកាត់តាមទ្វារដោយផ្អៀងតាមអង្កត់ទ្រូងបានឬទេ? ពន្យល់។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ប្រវែងអង្កត់ទ្រូងទ្វារ ៖ \(d = \sqrt{1^2 + 2^2} = \sqrt{1 + 4} = \sqrt{5}\ \text{m} pprox 2.236\ \text{m}\) (3 ពិន្ទុ)
ខ. បាន ព្រោះបន្ទះក្តារមូលមានអង្កត់ផ្ចិត \(2.2\ \text{m} < 2.236\ \text{m}\) (អង្កត់ទ្រូងទ្វារ) ដូច្នេះបើផ្អៀងបន្ទះក្តារតាមអង្កត់ទ្រូងទ្វារ គឺអាចឆ្លងកាត់បាន (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9350, 'នៅលើប្លង់ផែនទីមួយ ទីក្រុង \(A\) ស្ថិតនៅចម្ងាយ \(20\ \text{km}\) ខាងលិច និង \(9\ \text{km}\) ខាងជើងពីចំណុចកណ្តាល \(O\)។ ទីក្រុង \(B\) ស្ថិតនៅ \(15\ \text{km}\) ខាងកើត និង \(21\ \text{km}\) ខាងត្បូងពី \(O\)។
ក. គណនាចម្ងាយពី \(O\) ទៅទីក្រុង \(A\) (\(OA\))។
ខ. គណនាចម្ងាយពី \(O\) ទៅទីក្រុង \(B\) (\(OB\))។
គ. គណនាចម្ងាយត្រង់រវាងទីក្រុង \(A\) និងទីក្រុង \(B\) (\(AB\))។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(OA = \sqrt{(-20)^2 + 9^2} = \sqrt{400 + 81} = \sqrt{481}\ \text{km} pprox 21.93\ \text{km}\) (1 ពិន្ទុ)
ខ. \(OB = \sqrt{15^2 + (-21)^2} = \sqrt{225 + 441} = \sqrt{666} = 3\sqrt{74}\ \text{km} pprox 25.81\ \text{km}\) (2 ពិន្ទុ)
គ. \(AB = \sqrt{(15 - (-20))^2 + (-21 - 9)^2} = \sqrt{35^2 + (-30)^2} = \sqrt{1\,225 + 900} = \sqrt{2\,125} = 5\sqrt{85}\ \text{km} pprox 46.10\ \text{km}\) (2 ពិន្ទុ)', 'ទ្រឹស្តីបទពីតាក័រ', 'pisa', 0, '8', 'ទ្រឹស្តីបទពីតាក័រ', NULL, 0);
